template <typename T>
struct remove_ptr {
    using type = T;
};

// Partial Specialization for T*
template <typename T>
struct remove_ptr<T*> {
    using type = T;
};

// Convenience alias (C++11+)
template <typename T>
using remove_ptr_t = typename remove_ptr<T>::type;

// --- Example Transformation ---
using Original = const char* const;
// remove_ptr_t resolves to: const char
using Transformed = remove_ptr_t<Original>;
